async function deleteExistingSessions() {
  console.log("=== PASO 1: Eliminando sesiones existentes ===\n");

  // Obtener sesiones existentes del subject
  const url = BASE + "/sessions?subject_id=eq." + SUBJECT_ID + "&select=id,number,title";
  const r = await fetch(url, {method:"GET", headers:H});
  const existing = await r.json();

  if (!Array.isArray(existing) || existing.length === 0) {
    console.log("  No hay sesiones existentes para eliminar.\n");
    return;
  }

  console.log("  Sesiones encontradas: " + existing.length);

  for (const s of existing) {
    // Obtener quizzes de esta sesion
    const qUrl = BASE + "/quizzes?session_id=eq." + s.id + "&select=id";
    const qr = await fetch(qUrl, {method:"GET", headers:H});
    const quizzes = await qr.json();

    if (Array.isArray(quizzes) && quizzes.length > 0) {
      for (const q of quizzes) {
        // Eliminar quiz_questions
        await fetch(BASE + "/quiz_questions?quiz_id=eq." + q.id, {method:"DELETE", headers:Hm});
        // Eliminar quiz
        await fetch(BASE + "/quizzes?id=eq." + q.id, {method:"DELETE", headers:Hm});
      }
    }

    // Eliminar sesion
    const dr = await fetch(BASE + "/sessions?id=eq." + s.id, {method:"DELETE", headers:Hm});
    console.log("  Eliminada S" + s.number + ": " + s.title.substring(0, 40));
  }

  console.log("\n  Limpieza completada.\n");
}

async function post(url, body) {
  const r = await fetch(url, {method:"POST", headers:H, body:JSON.stringify(body)});
  return {status:r.status, data:await r.json()};
}

async function main() {
  // PASO 1: Eliminar sesiones existentes
  await deleteExistingSessions();

  // PASO 2: Cargar 16 sesiones nuevas
  console.log("=== PASO 2: Cargando 16 sesiones - Introduccion a la Ciencia de Datos ===\n");

  for (const s of sessions) {
    const {status, data} = await post(BASE + "/sessions", {
      subject_id: SUBJECT_ID,
      number: s.number,
      title: s.title,
      video_url: s.video,
      theory_markdown: s.theory,
      order_index: s.number,
      estimated_duration_minutes: 45,
      is_active: true
    });

    if (status !== 201) {
      console.log("  ERR S" + s.number + ": " + JSON.stringify(data).substring(0, 100));
      continue;
    }

    const sid = Array.isArray(data) ? data[0].id : data.id;
    let info = "  S" + s.number + " " + s.title.substring(0, 40) + " OK";

    if (s.quiz && s.quiz.length > 0) {
      const {status:qs, data:qd} = await post(BASE + "/quizzes", {
        session_id: sid,
        title: "Quiz - " + s.title,
        pass_percentage: 70,
        max_attempts: 3,
        is_active: true
      });

      if (qs === 201) {
        const qid = Array.isArray(qd) ? qd[0].id : qd.id;
        for (let i = 0; i < s.quiz.length; i++) {
          const q = s.quiz[i];
          await fetch(BASE + "/quiz_questions", {
            method: "POST",
            headers: Hm,
            body: JSON.stringify({
              quiz_id: qid,
              question_text: q.q,
              question_type: "multiple_choice",
              options: JSON.stringify([
                {id:"a", text:q.a, is_correct: q.correct === "a"},
                {id:"b", text:q.b, is_correct: q.correct === "b"},
                {id:"c", text:q.c, is_correct: q.correct === "c"},
                {id:"d", text:q.d, is_correct: q.correct === "d"}
              ]),
              explanation: q.exp,
              points: 1,
              order_index: i + 1
            })
          });
        }
        info += " | Q:" + s.quiz.length;
      } else {
        info += " | QUIZ ERR: " + JSON.stringify(qd).substring(0, 50);
      }
    }

    console.log(info);
  }

  console.log("\n=== COMPLETADO: 16 sesiones de Introduccion a la Ciencia de Datos ===");
  console.log("Subject ID: " + SUBJECT_ID);
}

main().catch(e => console.error("ERROR FATAL:", e));
